import csv
import io
import re


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].removeprefix("\ufeff")

    first = records[0]
    headerless = (
        len(first) >= 2
        and re.fullmatch(r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}", first[0].strip()) is not None
        and re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?", first[1].strip()) is not None
    )

    if headerless or not first:
        columns = []
        rows = records
    else:
        columns = first[:]
        rows = records[1:]

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        columns.append("column_" + str(len(columns) + 1))

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
